import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.resolve("/home/user/qwik-app/gallery.db");

let db: Database.Database;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    initializeDb(db);
  }
  return db;
}

function initializeDb(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS images (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      original_name TEXT NOT NULL,
      original_path TEXT NOT NULL,
      optimized_path TEXT NOT NULL,
      width INTEGER NOT NULL,
      height INTEGER NOT NULL,
      uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
  `);
}

export interface ImageRecord {
  id: number;
  original_name: string;
  original_path: string;
  optimized_path: string;
  width: number;
  height: number;
  uploaded_at: string;
}

import sharp from "sharp";
import path from "path";
import fs from "fs";
import { v4 as uuidv4 } from "uuid";

// We'll generate UUIDs without the uuid package to avoid extra deps
function generateId(): string {
  return Date.now().toString(36) + "-" + Math.random().toString(36).substring(2, 10);
}

const ORIGINAL_DIR = "/home/user/qwik-app/public/gallery/original";
const OPTIMIZED_DIR = "/home/user/qwik-app/public/gallery/optimized";
const MAX_DIMENSION = 800;

export interface OptimizeResult {
  originalName: string;
  originalPath: string;
  optimizedPath: string;
  width: number;
  height: number;
}

export async function saveAndOptimizeImage(
  buffer: Buffer,
  originalFilename: string,
): Promise<OptimizeResult> {
  // Ensure directories exist
  fs.mkdirSync(ORIGINAL_DIR, { recursive: true });
  fs.mkdirSync(OPTIMIZED_DIR, { recursive: true });

  const ext = path.extname(originalFilename);
  const baseId = generateId();
  const originalFilenameSaved = baseId + ext;
  const optimizedFilename = baseId + ".webp";

  const originalPath = path.join(ORIGINAL_DIR, originalFilenameSaved);
  const optimizedPath = path.join(OPTIMIZED_DIR, optimizedFilename);

  // Save original
  fs.writeFileSync(originalPath, buffer);

  // Get original dimensions
  const metadata = await sharp(buffer).metadata();
  const origWidth = metadata.width || 0;
  const origHeight = metadata.height || 0;

  // Determine resize dimensions
  let resizeWidth: number;
  let resizeHeight: number;

  if (origWidth <= MAX_DIMENSION && origHeight <= MAX_DIMENSION) {
    // Don't scale up — keep original dimensions
    resizeWidth = origWidth;
    resizeHeight = origHeight;
  } else {
    // Scale so the maximum dimension is MAX_DIMENSION
    if (origWidth >= origHeight) {
      resizeWidth = MAX_DIMENSION;
      resizeHeight = Math.round((origHeight / origWidth) * MAX_DIMENSION);
    } else {
      resizeHeight = MAX_DIMENSION;
      resizeWidth = Math.round((origWidth / origHeight) * MAX_DIMENSION);
    }
  }

  // Optimize and convert to WebP
  await sharp(buffer)
    .resize(resizeWidth, resizeHeight, { fit: "inside" })
    .webp({ quality: 80 })
    .toFile(optimizedPath);

  return {
    originalName: originalFilename,
    originalPath: "/gallery/original/" + originalFilenameSaved,
    optimizedPath: "/gallery/optimized/" + optimizedFilename,
    width: resizeWidth,
    height: resizeHeight,
  };
}

import { component$ } from "@builder.io/qwik";
import { routeLoader$ } from "@builder.io/qwik-city";
import { getDb, type ImageRecord } from "../../lib/db";

export const useImages = routeLoader$(async () => {
  const db = getDb();
  const rows = db
    .prepare("SELECT id, original_name, original_path, optimized_path, width, height, uploaded_at FROM images ORDER BY uploaded_at DESC")
    .all() as ImageRecord[];
  return rows;
});

export default component$(() => {
  const imagesSignal = useImages();

  return (
    <div>
      <h1>Image Gallery</h1>

      <section style={{ marginBottom: "2rem" }}>
        <h2>Upload an Image</h2>
        <form action="/gallery/upload" method="post" enctype="multipart/form-data">
          <div style={{ marginBottom: "0.5rem" }}>
            <input type="file" name="image" accept="image/*" />
          </div>
          <button type="submit">Upload</button>
        </form>
      </section>

      <section>
        <h2>Gallery</h2>
        {imagesSignal.value.length === 0 ? (
          <p>No images uploaded yet.</p>
        ) : (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))",
              gap: "1rem",
            }}
          >
            {imagesSignal.value.map((img) => (
              <div
                key={img.id}
                style={{
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  padding: "1rem",
                  textAlign: "center",
                }}
              >
                <img
                  src={img.optimized_path}
                  alt={img.original_name}
                  style={{ maxWidth: "100%", height: "auto", borderRadius: "4px" }}
                  loading="lazy"
                />
                <p style={{ margin: "0.5rem 0", fontWeight: "bold" }}>
                  {img.original_name}
                </p>
                <p style={{ margin: "0.25rem 0", color: "#666" }}>
                  {img.width}x{img.height}
                </p>
                <a href={img.original_path} target="_blank" rel="noopener noreferrer">
                  View Original
                </a>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
});

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "../../../lib/db";
import { saveAndOptimizeImage } from "../../../lib/image-optimizer";

export const onPost: RequestHandler = async ({ request, redirect }) => {
  const formData = await request.formData();
  const file = formData.get("image") as File | null;

  if (!file || !(file instanceof File) || file.size === 0) {
    throw redirect(303, "/gallery");
  }

  const buffer = Buffer.from(await file.arrayBuffer());
  const originalName = file.name || "unknown";

  const result = await saveAndOptimizeImage(buffer, originalName);

  const db = getDb();
  db.prepare(
    "INSERT INTO images (original_name, original_path, optimized_path, width, height) VALUES (?, ?, ?, ?, ?)"
  ).run(result.originalName, result.originalPath, result.optimizedPath, result.width, result.height);

  throw redirect(303, "/gallery");
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb, type ImageRecord } from "../../../lib/db";

export const onGet: RequestHandler = async ({ json }) => {
  const db = getDb();
  const rows = db
    .prepare(
      "SELECT id, original_name, original_path, optimized_path, width, height, uploaded_at FROM images ORDER BY uploaded_at DESC"
    )
    .all() as ImageRecord[];

  const result = rows.map((row) => ({
    id: row.id,
    original_name: row.original_name,
    original_path: row.original_path,
    optimized_path: row.optimized_path,
    width: row.width,
    height: row.height,
  }));

  json(200, result);
};

